
'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { X, UserPlus, UserMinus, Search } from 'lucide-react';
import { PlaceholdersAndVanishInput } from '@/components/ui/placeholders-and-vanish-input';
import { useSearchParams, useRouter } from 'next/navigation';
import { Input } from '@/components/ui/input'; 
import { Suspense } from 'react';

type Member = {
  id: number;
  name: string;
  topics: string[];
  institution: string;
};

function TopicContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const mode = searchParams.get('mode') || 'individual';
  const type = searchParams.get('type') || 'work';
  const [institution, setInstitution] = useState('');
  const [topic, setTopic] = useState('');
  const [topics, setTopics] = useState<string[]>([]);
  const [members, setMembers] = useState<Member[]>([
    { id: 1, name: 'Member 1', topics: [], institution: '' },
    { id: 2, name: 'Member 2', topics: [], institution: '' },
  ]);
  const [activeMemberId, setActiveMemberId] = useState<number | null>(
    mode === 'group' ? 1 : null
  );


  const placeholders = [
    "What's your favorite movie genre?",
    "Let's talk about travel destinations",
    "Suggest some good sci-fi books",
    "I'm looking for a new recipe",
    "What's the best way to learn a new language?",
  ];




  const addInstitutionToMember = (memberId: number, institution: string) => {
    setMembers(prevMembers =>
      prevMembers.map(m =>
        m.id === memberId ? { ...m, institution } : m
      )
    );
  };


  


  const handleAddTopic = (e: React.FormEvent) => {
    e.preventDefault();
    if (topic.trim() === '') return;

    if (mode === 'individual') {
      if (!topics.includes(topic.trim())) {
        setTopics([...topics, topic.trim()]);
      }
    } else {
      if (activeMemberId) {
        setMembers(members.map(member =>
          member.id === activeMemberId && !member.topics.includes(topic.trim())
            ? { ...member, topics: [...member.topics, topic.trim()] }
            : member
        ));
      }
    }
    setTopic('');
  };

  const handleRemoveTopic = (topicToRemove: string, memberId?: number) => {
    if (mode === 'individual') {
      setTopics(topics.filter(t => t !== topicToRemove));
    } else {
      setMembers(members.map(member =>
        member.id === memberId
          ? { ...member, topics: member.topics.filter(t => t !== topicToRemove) }
          : member
      ));
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setTopic(e.target.value);
  };
  
  const addMember = () => {
    if (members.length < 5) {
      const newId = members.length > 0 ? Math.max(...members.map(m => m.id)) + 1 : 1;
      setMembers([...members, { id: newId, name: `Member ${newId}`, topics: [] }]);
    }
  };

  const removeMember = () => {
    if (members.length > 2) {
      const memberToRemove = members[members.length - 1];
      if (activeMemberId === memberToRemove.id) {
        setActiveMemberId(members[0].id);
      }
      setMembers(members.slice(0, -1));
    }
  };

  // const handleSearch = () => {
  //   const queryParams = new URLSearchParams();
  //   queryParams.set('mode', mode);

  //   if (mode === 'individual') {
  //     queryParams.set('topics', topics.join(','));
  //   } else {
  //      members.forEach(member => {
  //       queryParams.append(`member_${member.id}`, member.topics.join(','));
  //      });
  //   }

  //   const destination = type === 'author' ? '/author-recommendations' : '/recommendations';
    
  //   router.push(`${destination}?${queryParams.toString()}`);
  // };


  const handleSearch = () => {
    const queryParams = new URLSearchParams();
    queryParams.set('mode', mode);

    if (mode === 'individual') {
      queryParams.set('topics', topics.join(','));
      queryParams.set('institution', institution);
    } else {
      members.forEach(member => {
        queryParams.append(`member_${member.id}`, member.topics.join(','));
        queryParams.append(`member_${member.id}_institution`, member.institution); // <-- Add institution for each member
      });
    }

    const destination = type === 'author' ? '/author-recommendations' : '/recommendations';
    router.push(`${destination}?${queryParams.toString()}`);
  };


  const isSearchDisabled = () => {
    if (mode === 'individual') {
      return topics.length === 0;
    } else {
      return members.every(member => member.topics.length === 0);
    }
  };



  

  return (
       <div className="flex min-h-screen w-full flex-col items-center p-4 pt-20 bg-transparent">
      <div className="w-full max-w-xl">
        {/* Individual Mode */}
        {mode === 'individual' && (
          <>
            {/* Topics Input */}
            <PlaceholdersAndVanishInput
              placeholders={placeholders}
              onChange={handleChange}
              onSubmit={onSubmit}
            />

            {/* Institution Input */}
            <div className="mt-4">
              <input
                type="text"
                className="w-full px-4 py-2 rounded-lg border border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 placeholder-neutral-500 dark:placeholder-neutral-400 focus:outline-none focus:ring-2 focus:ring-primary"
                placeholder="Enter your institution (optional)"
                value={institution}
                onChange={e => setInstitution(e.target.value)}
              />
            </div>

            {/* Display topics */}
            {topics.length > 0 && (
              <div className="mt-4 flex flex-wrap gap-2">
                {topics.map((t, idx) => (
                  <div key={idx} className="px-3 py-1 bg-primary/10 rounded-full text-sm">
                    {t}
                    <button
                      className="ml-2 text-destructive"
                      onClick={() => setTopics(topics.filter((_, i) => i !== idx))}
                    >
                      ×
                    </button>
                  </div>
                ))}
              </div>
            )}
          </>
        )}

        {/* Group Mode */}
        {mode === 'group' && (
          <>
            {/* Member selector */}
            <div className="mb-6 flex gap-2 flex-wrap">
              {members.map(member => (
                <button
                  key={member.id}
                  className={`px-4 py-2 rounded ${
                    activeMemberId === member.id
                      ? 'bg-primary text-white'
                      : 'bg-neutral-200 dark:bg-neutral-800'
                  }`}
                  onClick={() => setActiveMemberId(member.id)}
                >
                  {member.name}
                </button>
              ))}
            </div>

            {/* Active member topics input */}
            {activeMemberId && (
              <>
                <PlaceholdersAndVanishInput
                  placeholders={placeholders}
                  onChange={handleChange}
                  onSubmit={(e) => {
                    e.preventDefault();
                    if (topic.trim() && activeMemberId) {
                      addTopicToMember(activeMemberId, topic.trim());
                      setTopic('');
                    }
                  }}
                />

                {/* Institution input for active member */}
                <div className="mt-4">
                  <input
                    type="text"
                    className="w-full px-4 py-2 rounded-lg border border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-neutral-100 placeholder-neutral-500 dark:placeholder-neutral-400 focus:outline-none focus:ring-2 focus:ring-primary"
                    placeholder={`Enter institution for ${members.find(m => m.id === activeMemberId)?.name} (optional)`}
                    value={members.find(m => m.id === activeMemberId)?.institution || ''}
                    onChange={e => addInstitutionToMember(activeMemberId, e.target.value)}
                  />
                </div>

                {/* Display topics for active member */}
                {members.find(m => m.id === activeMemberId)?.topics.length > 0 && (
                  <div className="mt-4 flex flex-wrap gap-2">
                    {members.find(m => m.id === activeMemberId)?.topics.map((t, idx) => (
                      <div key={idx} className="px-3 py-1 bg-primary/10 rounded-full text-sm">
                        {t}
                        <button
                          className="ml-2 text-destructive"
                          onClick={() => removeTopicFromMember(activeMemberId, idx)}
                        >
                          ×
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </>
            )}
          </>
        )}

        {/* Submit button */}
        <button
          className="mt-8 w-full px-6 py-3 bg-primary text-white rounded-lg hover:bg-primary/80 transition disabled:opacity-50"
          onClick={handleSearch}
          disabled={mode === 'individual' ? topics.length === 0 : members.every(m => m.topics.length === 0)}
        >
          Get Recommendations
        </button>
      </div>
    </div>
  );
}


export default function TopicPage() {
  return (
    <Suspense fallback={<div>Loading...</div>}>
      <TopicContent />
    </Suspense>
  );
}
